"""A3 local receipts and exact manifest; no models, runtime recovery or experiments."""
import hashlib,json,platform,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
BASE=ROOT/'semantic_pallet_planner/outputs';A2=BASE/'JEV_JM2_A2_20261115_01';QA=BASE/'JEV_JM2_A2_QA_20261115_01'
